function(container, apiUrl, tables) {
  // 業務ロジックのインポート
  const { 
    collectSalesData, 
    classifySalesDataByProduct, 
    classifySalesDataByStore, 
    filterValidProductData, 
    collectWeatherData, 
    collectEventData, 
    collectSeasonalData, 
    analyzeCorrelationSalesWeather, 
    analyzeCorrelationSalesEvent, 
    analyzeCorrelationSalesSeason, 
    compareWithHistoricalData, 
    findAlternativeComparisonData, 
    validateComparisonPeriod 
  } = window.aiLogic || {};

  let editingModelId = null;

  // テーブル再描画関数
  function renderRows(rows) {
    const tbody = container.querySelector("#model-list-tbody");
    if (!tbody) return;
    tbody.innerHTML = rows.map(r => `
      <tr data-id="${r.id}">
        <td>${r.モデル名 || ""}</td>
        <td>${r.対象店舗名 || ""}</td>
        <td>${r.対象商品カテゴリ || ""}</td>
        <td>${r.アルゴリズム || ""}</td>
        <td>${r.モデル精度目標値 || ""}%</td>
        <td><span class="status-badge ${r.ステータス === '作成完了' ? 'success' : 'pending'}">${r.ステータス || ""}</span></td>
        <td>${r.作成日時 ? new Date(r.作成日時).toLocaleDateString() : ""}</td>
        <td>
          <button class="action-btn secondary edit-btn" data-id="${r.id}">編集</button>
          <button class="action-btn secondary delete-btn" data-id="${r.id}">削除</button>
        </td>
      </tr>
    `).join("");

    // 編集・削除ボタンのイベントハンドラを再設定
    attachRowEventHandlers();
  }

  // 店舗データを読み込んでセレクトボックスに設定
  async function loadStores() {
    try {
      const stores = await window.aivicApi.list(1); // 店舗マスタ
      const storeSelect = container.querySelector("#target-store");
      if (stores && storeSelect) {
        storeSelect.innerHTML = '<option value="">選択してください</option>' + 
          stores.map(store => `<option value="${store.id}">${store.店舗名}</option>`).join("");
      }
    } catch (error) {
      window.aivicNotify.error("店舗データの読み込みに失敗しました");
    }
  }

  // 商品カテゴリのチェックボックスを生成
  function loadCategories() {
    const categories = ["食品", "飲料", "日用品", "衣料品", "家電", "書籍", "その他"];
    const categoryContainer = container.querySelector("#category-checkboxes");
    if (categoryContainer) {
      categoryContainer.innerHTML = categories.map(cat => `
        <label class="checkbox-item">
          <input type="checkbox" name="product-category" value="${cat}"> ${cat}
        </label>
      `).join("");
    }
  }

  // フォームリセット
  function resetForm() {
    const form = container.querySelector("#model-form");
    if (form) form.reset();
    editingModelId = null;

    const editIdField = container.querySelector("#edit-model-id");
    if (editIdField) editIdField.value = "";

    const formTitle = container.querySelector("#form-title");
    if (formTitle) formTitle.textContent = "新規モデル作成";

    const saveBtn = container.querySelector("#btn-save");
    if (saveBtn) saveBtn.textContent = "モデル作成";

    // チェックボックスをリセット
    container.querySelectorAll('input[type="checkbox"]').forEach(cb => cb.checked = false);

    const defaultPeriod = container.querySelector('input[name="prediction-period"][value="30"]');
    if (defaultPeriod) defaultPeriod.checked = true;
  }

  // フォームにデータを設定（編集時）
  function populateForm(model) {
    const modelNameField = container.querySelector("#model-name");
    if (modelNameField) modelNameField.value = model.モデル名 || "";

    const storeField = container.querySelector("#target-store");
    if (storeField) storeField.value = model.対象店舗ID || "";

    const startDateField = container.querySelector("#learning-start-date");
    if (startDateField) startDateField.value = model.学習期間開始日 || "";

    const endDateField = container.querySelector("#learning-end-date");
    if (endDateField) endDateField.value = model.学習期間終了日 || "";

    if (model.予測期間) {
      const periodRadio = container.querySelector(`input[name="prediction-period"][value="${model.予測期間}"]`);
      if (periodRadio) periodRadio.checked = true;
    }

    const algorithmField = container.querySelector("#algorithm");
    if (algorithmField) algorithmField.value = model.アルゴリズム || "ARIMA";

    const learningRateField = container.querySelector("#learning-rate");
    if (learningRateField) {
      learningRateField.value = model.学習率 || 0.01;
      const learningRateValue = container.querySelector("#learning-rate-value");
      if (learningRateValue) learningRateValue.textContent = model.学習率 || 0.01;
    }

    const accuracyField = container.querySelector("#accuracy-target");
    if (accuracyField) accuracyField.value = model.モデル精度目標値 || 85;

    // 商品カテゴリのチェックボックス設定
    if (model.対象商品カテゴリ) {
      const categories = model.対象商品カテゴリ.split(',');
      categories.forEach(cat => {
        const checkbox = container.querySelector(`input[name="product-category"][value="${cat.trim()}"]`);
        if (checkbox) checkbox.checked = true;
      });
    }

    editingModelId = model.id;
    const editIdField = container.querySelector("#edit-model-id");
    if (editIdField) editIdField.value = model.id;

    const formTitle = container.querySelector("#form-title");
    if (formTitle) formTitle.textContent = "モデル編集";

    const saveBtn = container.querySelector("#btn-save");
    if (saveBtn) saveBtn.textContent = "更新";
  }

  // フォームデータ収集
  function collectFormData() {
    const modelName = container.querySelector("#model-name")?.value || "";
    const targetStore = container.querySelector("#target-store")?.value || "";
    const learningStartDate = container.querySelector("#learning-start-date")?.value || "";
    const learningEndDate = container.querySelector("#learning-end-date")?.value || "";
    const algorithm = container.querySelector("#algorithm")?.value || "ARIMA";
    const learningRate = parseFloat(container.querySelector("#learning-rate")?.value || 0.01);
    const accuracyTarget = parseInt(container.querySelector("#accuracy-target")?.value || 85);

    const predictionPeriod = container.querySelector('input[name="prediction-period"]:checked')?.value || "30";

    const selectedCategories = Array.from(container.querySelectorAll('input[name="product-category"]:checked'))
      .map(cb => cb.value);

    return {
      モデル名: modelName,
      対象店舗ID: targetStore,
      学習期間開始日: learningStartDate,
      学習期間終了日: learningEndDate,
      予測期間: predictionPeriod,
      アルゴリズム: algorithm,
      学習率: learningRate,
      モデル精度目標値: accuracyTarget,
      対象商品カテゴリ: selectedCategories.join(','),
      ステータス: "作成中"
    };
  }

  // モデル保存処理
  async function saveModel() {
    try {
      const formData = collectFormData();

      // バリデーション
      if (!formData.モデル名) {
        window.aivicNotify.error("モデル名を入力してください");
        return;
      }

      if (!formData.対象店舗ID) {
        window.aivicNotify.error("対象店舗を選択してください");
        return;
      }

      if (!formData.学習期間開始日 || !formData.学習期間終了日) {
        window.aivicNotify.error("学習期間を設定してください");
        return;
      }

      // 期間バリデーション（業務ロジック使用）
      if (validateComparisonPeriod) {
        const isValidPeriod = validateComparisonPeriod(formData.学習期間開始日, formData.学習期間終了日);
        if (!isValidPeriod) {
          window.aivicNotify.error("学習期間の設定が不正です");
          return;
        }
      }

      // 売上データ収集（業務ロジック使用）
      let salesData = null;
      if (collectSalesData) {
        salesData = await collectSalesData(formData.対象店舗ID, formData.学習期間開始日, formData.学習期間終了日);

        if (filterValidProductData && salesData) {
          salesData = filterValidProductData(salesData);
        }
      }

      // 相関データ分析（業務ロジック使用）
      if (salesData && analyzeCorrelationSalesWeather && collectWeatherData) {
        const weatherData = await collectWeatherData(formData.学習期間開始日, formData.学習期間終了日);
        const weatherCorrelation = analyzeCorrelationSalesWeather(salesData, weatherData);
        formData.天候相関度 = weatherCorrelation;
      }

      if (salesData && analyzeCorrelationSalesEvent && collectEventData) {
        const eventData = await collectEventData(formData.学習期間開始日, formData.学習期間終了日);
        const eventCorrelation = analyzeCorrelationSalesEvent(salesData, eventData);
        formData.イベント相関度 = eventCorrelation;
      }

      // データ保存
      let result;
      if (editingModelId) {
        result = await window.aivicApi.update(6, editingModelId, formData); // AIモデル設定テーブル
      } else {
        result = await window.aivicApi.save(6, formData); // AIモデル設定テーブル
      }

      if (result) {
        window.aivicNotify.success(editingModelId ? "モデルを更新しました" : "モデルを作成しました");
        resetForm();
        await loadModels();
      }
    } catch (error) {
      console.error("モデル保存エラー:", error);
      window.aivicNotify.error("モデルの保存に失敗しました");
    }
  }

  // モデル一覧読み込み
  async function loadModels() {
    try {
      const models = await window.aivicApi.list(6); // AIモデル設定テーブル
      if (models) {
        // 店舗名を取得して結合
        const stores = await window.aivicApi.list(1);
        const storeMap = {};
        if (stores) {
          stores.forEach(store => {
            storeMap[store.id] = store.店舗名;
          });
        }

        const modelsWithStoreName = models.map(model => ({
          ...model,
          対象店舗名: storeMap[model.対象店舗ID] || ""
        }));

        renderRows(modelsWithStoreName);
      }
    } catch (error) {
      console.error("モデル読み込みエラー:", error);
      window.aivicNotify.error("モデル一覧の読み込みに失敗しました");
    }
  }

  // モデル削除
  async function deleteModel(modelId) {
    if (!confirm("このモデルを削除しますか？")) return;

    try {
      await window.aivicApi.delete(6, modelId);
      window.aivicNotify.success("モデルを削除しました");
      await loadModels();
    } catch (error) {
      console.error("モデル削除エラー:", error);
      window.aivicNotify.error("モデルの削除に失敗しました");
    }
  }

  // 行のイベントハンドラ設定
  function attachRowEventHandlers() {
    // 編集ボタン
    container.querySelectorAll(".edit-btn").forEach(btn => {
      btn.addEventListener("click", async (e) => {
        const modelId = e.target.getAttribute("data-id");
        try {
          const models = await window.aivicApi.list(6);
          const model = models.find(m => m.id == modelId);
          if (model) {
            populateForm(model);
          }
        } catch (error) {
          window.aivicNotify.error("モデル情報の取得に失敗しました");
        }
      });
    });

    // 削除ボタン
    container.querySelectorAll(".delete-btn").forEach(btn => {
      btn.addEventListener("click", (e) => {
        const modelId = e.target.getAttribute("data-id");
        deleteModel(modelId);
      });
    });
  }

  // 学習率スライダーの値表示更新
  function updateLearningRateDisplay() {
    const learningRateSlider = container.querySelector("#learning-rate");
    const learningRateValue = container.querySelector("#learning-rate-value");

    if (learningRateSlider && learningRateValue) {
      learningRateSlider.addEventListener("input", (e) => {
        learningRateValue.textContent = e.target.value;
      });
    }
  }

  // イベントハンドラの設定
  function attachEventHandlers() {
    // 保存ボタン
    const saveBtn = container.querySelector("#btn-save");
    if (saveBtn) {
      saveBtn.addEventListener("click", saveModel);
    }

    // キャンセルボタン
    const cancelBtn = container.querySelector("#btn-cancel");
    if (cancelBtn) {
      cancelBtn.addEventListener("click", resetForm);
    }

    // 新規作成ボタン
    const newBtn = container.querySelector("#btn-new-model");
    if (newBtn) {
      newBtn.addEventListener("click", resetForm);
    }

    // 学習率スライダー
    updateLearningRateDisplay();
  }

  // 初期化処理
  async function initialize() {
    try {
      await loadStores();
      loadCategories();
      await loadModels();
      attachEventHandlers();
      resetForm();
    } catch (error) {
      console.error("初期化エラー:", error);
      window.aivicNotify.error("画面の初期化に失敗しました");
    }
  }

  // 初期化実行
  initialize();
}
